 "elements": [
 {
 "type": "field",
 "label": "Name",
 "control": {
 "type": "input",
 "path": "personal/name",
 "placeholder": "Enter your full name",
 "size": "md"
 }
 },
 {
 "type": "field",
 "label": "Phone",
 "control": {
 "type": "input",
 "path": "personal/phone",
 "placeholder": "+1 (555) 000-0000",
 "mode": "tel",
 "size": "md"
 }
 },
 {
 "type": "field",
 "label": "ZIP Code",
 "control": {
 "type": "number",
 "path": "address/zip",
 "placeholder": "12345",
